function detectExplicitFilesystemIntent(text: string): boolean {
  if (!text) return false;
  const hasPathHint = /\b(?:src\/[a-zA-Z0-9_./-]+|server\.ts|package\.json|metadata\.json|tsconfig\.json|firestore\.rules|[a-zA-Z0-9_-]+\.(?:tsx?|jsx?|json|css|md|sql|sh|py))\b/i.test(text);
  const hasFsVerb = /\b(?:read|inspect|open|check|audit|write|rewrite|create|build|design|forge|synthesize|patch|atomic[\s_-]*patch|edit|modify|update|fix|refactor|rollback|search|find|grep|list|scan|lint|compile|tsc|verify)\b/i.test(text)
    && /\b(?:file|files|code|codebase|dir|directory|folder|workspace|repo|component|module|window|panel|widget|feature|endpoint|route|tool|utility|calculator|simulator|server|line|lines|bug|error|patch|diff|script|config)\b/i.test(text);
  return hasPathHint || hasFsVerb;
}

async function executeProactiveOfflineFilesystemOps(
  promptText: string,
  agentId: string
): Promise<Array<{ tag: string; action: string; success: boolean; summary: string; output: any; diff?: string }>> {
  const results: Array<{ tag: string; action: string; success: boolean; summary: string; output: any; diff?: string }> = [];
  if (!promptText) return results;

  const explicitFiles = Array.from(
    new Set(
      (promptText.match(/\b(?:src\/[a-zA-Z0-9_./-]+\.[a-zA-Z0-9]+|server\.ts|package\.json|metadata\.json|tsconfig\.json|vite\.config\.ts|index\.html)\b/g) || [])
        .slice(0, 4)
    )
  );
  const wantsReadOrInspect = /\b(?:read|inspect|open|view|show|check|contents?|lines?|audit)\b/i.test(promptText);
  if (explicitFiles.length > 0 && wantsReadOrInspect) {
    for (const fp of explicitFiles) {
      results.push(await executeServerSovereignTool('readFile', { filePath: fp, scope: 'auto', startLine: 1, endLine: 180 }, agentId));
    }
  }

  if (/\b(?:list\s+(?:files?|dir|directory|folder|workspace|root)|what\s+files\s+are)\b/i.test(promptText)) {
    results.push(await executeServerSovereignTool('listDirectory', { dirPath: '.', scope: 'auto' }, agentId));
  }

  if (/\b(?:run\s+lint|typecheck|check\s+(?:types|build|tsc)|npm\s+run\s+lint)\b/i.test(promptText)) {
    results.push(await executeServerSovereignTool('runLint', {}, agentId));
  }

  const searchMatch = promptText.match(/\b(?:search|grep|find)\s+(?:for\s+)?["'`]([^"'`]{2,64})["'`]/i);
  if (searchMatch && searchMatch[1]) {
    results.push(await executeServerSovereignTool('searchCode', { query: searchMatch[1] }, agentId));
  }

  return results;
}

// Adaptive circuit-breaker, latency tracker, and loop-safe daemon probes for API call chain

function withPromiseTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => {
      const err: any = new Error(`Call timed out after ${ms}ms (${label})`);
      err.status = 504;
      err.isTimeout = true;
      reject(err);
    }, ms);
    promise.then(
      (val) => { clearTimeout(timer); resolve(val); },
      (err) => { clearTimeout(timer); reject(err); }
    );
  });
}

async function isExternalLlama8080Alive(): Promise<boolean> {
  try {
    const r = await fetch('http://127.0.0.1:8080/health', {
      headers: { 'x-aurelius-loop-guard': AURELIUS_INSTANCE_ID },
      signal: AbortSignal.timeout(400)
    });
    if (!r.ok) return false;
    // Reject nginx reverse-proxy pointing back to this Express instance or SPA HTML fallback
    if (r.headers.get('x-aurelius-instance') === AURELIUS_INSTANCE_ID) return false;
    const ct = (r.headers.get('content-type') || '').toLowerCase();
    if (ct.includes('text/html')) return false;
    return true;
  } catch {
    return false;
  }
}

async function isExternalOllamaAlive(): Promise<boolean> {
  try {
    const host = (internalSecretsHandler.getSecret('OLLAMA_HOST') || 'http://127.0.0.1:11434').replace(/\/$/, '');
    const r = await fetch(`${host}/api/version`, { signal: AbortSignal.timeout(400) });
    return r.ok;
  } catch {
    return false;
  }
}

function isQuotaOrRateLimitError(err: any): boolean {
  const status = err?.status || err?.code || 0;
  const msg = String(err?.message || '').toLowerCase();
  return status === 429 || msg.includes('resource_exhausted') || msg.includes('quota exceeded') || msg.includes('"code":429');
}

function parseRetryDelayMs(err: any): number {
  const msg = String(err?.message || '');
  const retryMatch = msg.match(/"retryDelay"\s*:\s*"(\d+)s"/i) || msg.match(/retry in\s+(\d+(?:\.\d+)?)s/i);
  if (retryMatch) {
    const secs = Math.ceil(parseFloat(retryMatch[1]));
    return Math.min(Math.max(secs * 1000, 15_000), 600_000);
  }
  return msg.toLowerCase().includes('perday') ? 600_000 : 60_000;
}

function applyModelCooldown(modelName: string, err: any) {
  if (!modelName || !isQuotaOrRateLimitError(err)) return;
  const delayMs = parseRetryDelayMs(err);
  rateLimitedCooldowns.set(modelName, Date.now() + delayMs);
}

function recordModelSuccess(modelName: string, ms: number) {
  if (!modelName) return;
  lastHealthyGeminiModel = modelName;
  modelFailureCooldowns.delete(modelName);
  rateLimitedCooldowns.delete(modelName);
  const prev = modelLatencyStats.get(modelName) || { avgMs: ms, successes: 0, failures: 0 };
  const totalSuccess = prev.successes + 1;
  const newAvg = prev.successes === 0 ? ms : Math.round((prev.avgMs * 0.7) + (ms * 0.3));
  modelLatencyStats.set(modelName, { avgMs: newAvg, successes: totalSuccess, failures: prev.failures });
}

function recordModelFailure(modelName: string, err: any) {
  if (!modelName) return;
  const status = Number(err?.status || err?.code || 0);
  const msg = String(err?.message || err || 'error');
  const prev = modelLatencyStats.get(modelName) || { avgMs: 0, successes: 0, failures: 0 };
  modelLatencyStats.set(modelName, {
    avgMs: prev.avgMs,
    successes: prev.successes,
    failures: prev.failures + 1,
    lastError: msg.slice(0, 140)
  });

  if (isQuotaOrRateLimitError(err)) {
    applyModelCooldown(modelName, err);
    return;
  }

  let cooldownMs = 30_000;
  let reason = `status_${status || 'err'}`;
  if (status === 404 || /not found|not supported for generateContent|does not exist/i.test(msg)) {
    cooldownMs = 1_800_000; // 30 minutes for unsupported model aliases
    reason = 'unsupported_model';
  } else if (err?.isTimeout || status === 504 || /timed out|timeout/i.test(msg)) {
    cooldownMs = 120_000; // 2 minutes for stalled/timed-out candidate
    reason = 'timeout';
  } else if (status >= 500) {
    cooldownMs = 45_000;
    reason = 'upstream_5xx';
  }
  modelFailureCooldowns.set(modelName, { until: Date.now() + cooldownMs, reason, status });
  if (lastHealthyGeminiModel === modelName) {
    lastHealthyGeminiModel = '';
  }
}

function isModelInCooldown(modelName: string): boolean {
  const rateUntil = rateLimitedCooldowns.get(modelName);
  if (rateUntil) {
    if (Date.now() < rateUntil) return true;
    rateLimitedCooldowns.delete(modelName);
  }
  const failEntry = modelFailureCooldowns.get(modelName);
  if (failEntry) {
    if (Date.now() < failEntry.until) return true;
    modelFailureCooldowns.delete(modelName);
  }
  return false;
}

const DEFAULT_GEMINI_CASCADE = [
  'gemini-4-hydrogen',
  'gemini-3.1-flash-lite',
  'gemini-3-flash-preview',
  'gemini-4-neon',
  'gemini-4-argon',
  'gemini-4-carbon',
  'gemini-flash-latest',
  'gemini-flash-lite-latest',
  'gemini-3.1-flash-lite-preview',
  'gemma-4-31b-it',
  'gemma-4-26b-a4b-it'
];

function compactToolPayloadForChat(output: any, maxChars: number = 6500): any {
  if (output === null || output === undefined) return output;
  if (typeof output === 'string') {
    return output.length > maxChars ? `${output.slice(0, maxChars)}\n...[truncated ${output.length - maxChars} chars]` : output;
  }
  try {
    const serialized = JSON.stringify(output);
    if (serialized.length <= maxChars) return output;
    if (typeof output === 'object' && !Array.isArray(output)) {
      const compactObj: Record<string, any> = {};
      for (const [k, v] of Object.entries(output)) {
        if (k === 'fullProjectMerkleAudit' && v && typeof v === 'object') {
          const m = v as any;
          compactObj[k] = {
            totalFiles: m.totalFiles,
            totalCodeLines: m.totalCodeLines,
            merkleRootSha256: m.merkleRootSha256,
            zeroFileLossVerified: m.zeroFileLossVerified
          };
          continue;
        }
        if (k === 'modules' && Array.isArray(v)) {
          compactObj[k] = v.map((mod: any) => ({
            id: mod?.id,
            title: mod?.title,
            status: mod?.status,
            lineCount: mod?.lineCount,
            subfunctions: Array.isArray(mod?.subfunctions) ? mod.subfunctions.length : 0
          }));
          continue;
        }
        const vs = typeof v === 'string' ? v : JSON.stringify(v);
        if (vs && vs.length > 1400) {
          compactObj[k] = typeof v === 'string'
            ? `${v.slice(0, 1400)}...[truncated]`
            : `${vs.slice(0, 1400)}...[truncated]`;
        } else {
          compactObj[k] = v;
        }
      }
      const reSerialized = JSON.stringify(compactObj);
      if (reSerialized.length <= maxChars) return compactObj;
      return `${reSerialized.slice(0, maxChars)}...[truncated ${reSerialized.length - maxChars} chars]`;
    }
    return `${serialized.slice(0, maxChars)}...[truncated ${serialized.length - maxChars} chars]`;
  } catch {
    return String(output).slice(0, maxChars);
  }
}

function resolveCanonicalGeminiAlias(raw?: string): string | null {
  if (!raw || typeof raw !== 'string') return null;
  const trimmed = raw.trim();
  const lower = trimmed.toLowerCase();
  if (!lower) return null;
  if (lower === 'argon' || lower === 'gemini-4-argon') return 'gemini-4-argon';
  if (lower === 'neon' || lower === 'yourself' || lower === 'gemini-4-neon') return 'gemini-4-neon';
  if (lower === 'carbon' || lower === 'gemini-4-carbon') return 'gemini-4-carbon';
  if (lower === 'hydrogen' || lower === 'gemini-4-hydrogen') return 'gemini-4-hydrogen';
  if (lower === 'flash-lite' || lower === 'gemini-3.1-flash-lite') return 'gemini-3.1-flash-lite';
  if (lower === 'omni' || lower === 'gemini-omni-1.2-flash') return 'gemini-omni-1.2-flash';
  if (lower === 'decision' || lower === 'gemini-decision-1') return 'gemini-decision-1';
  if (lower.startsWith('gemini-') || lower.startsWith('gemma-')) return trimmed;
  return null;
}

function getGeminiCascadeModels(preferredModel?: string): string[] {
  const resolvedPreferred = resolveCanonicalGeminiAlias(preferredModel);
  const rawList = [
    ...(resolvedPreferred ? [resolvedPreferred] : []),
    ...(lastHealthyGeminiModel && !isModelInCooldown(lastHealthyGeminiModel) ? [lastHealthyGeminiModel] : []),
    ...DEFAULT_GEMINI_CASCADE
  ].filter((m, idx, arr) => m && arr.indexOf(m) === idx);

  const available = rawList.filter(m => !isModelInCooldown(m));
  if (available.length > 0) return available;

  // If every model is in transient cooldown, try up to 3 whose cooldown expires soonest
  return [...rawList]
    .sort((a, b) => {
      const aUntil = Math.max(rateLimitedCooldowns.get(a) || 0, modelFailureCooldowns.get(a)?.until || 0);
      const bUntil = Math.max(rateLimitedCooldowns.get(b) || 0, modelFailureCooldowns.get(b)?.until || 0);
      return aUntil - bUntil;
    })
    .slice(0, 3);
}

