const SCRATCHPADS_FILE = path.join(process.cwd(), 'data', 'scratchpads.json');
type ScratchpadRecord = {
  id: string;
  title: string;
  category: 'working-memory' | 'semantic-cache' | 'directives' | 'hfid-dossier' | 'code-drafts';
  content: string;
  tags: string[];
  hfidHash: string;
  attested: boolean;
  createdAt: string;
  updatedAt: string;
};

const DEFAULT_SCRATCHPADS: ScratchpadRecord[] = [
  {
    id: 'sp-001',
    title: 'Lysander 3.1 Enterprise Cross-Bridge Invariants',
    category: 'directives',
    content: `# Lysander 3.1 Enterprise Invariants\n- Workspace Autonomy & Atomic Patching active.\n- AES-256-GCM Internal Secrets Vault guarding all provider keys.\n- Compiler gate verification active via tsc --noEmit.`,
    tags: ['lysander', 'cbp', 'hfid', 'sovereign'],
    hfidHash: '7f38fa8ce6a6d3abd6e6d1a836958d',
    attested: true,
    createdAt: new Date(Date.now() - 1000 * 60 * 120).toISOString(),
    updatedAt: new Date(Date.now() - 1000 * 60 * 10).toISOString()
  },
  {
    id: 'sp-002',
    title: 'Sovereign Working Memory Buffer',
    category: 'working-memory',
    content: `Active persistent scratchpad buffer for task decomposition, code notes, and architectural planning.`,
    tags: ['scratchpad', 'working-memory'],
    hfidHash: '8836e9c9888f60bd07693',
    attested: true,
    createdAt: new Date(Date.now() - 1000 * 60 * 90).toISOString(),
    updatedAt: new Date().toISOString()
  }
];

function loadScratchpads(): ScratchpadRecord[] {
  try {
    if (fs.existsSync(SCRATCHPADS_FILE)) {
      const parsed = JSON.parse(fs.readFileSync(SCRATCHPADS_FILE, 'utf-8'));
      if (Array.isArray(parsed)) return parsed;
    }
  } catch {}
  return DEFAULT_SCRATCHPADS;
}

function persistScratchpads(pads: ScratchpadRecord[]) {
  try {
    fs.mkdirSync(path.dirname(SCRATCHPADS_FILE), { recursive: true });
    const tmp = `${SCRATCHPADS_FILE}.tmp-${process.pid}-${Date.now()}`;
    fs.writeFileSync(tmp, JSON.stringify(pads, null, 2));
    fs.renameSync(tmp, SCRATCHPADS_FILE);
  } catch (err) {
    console.warn('[SCRATCHPADS] Persist error:', err);
  }
}

let scratchpadStore: ScratchpadRecord[] = loadScratchpads();

app.get('/api/scratchpads', (req, res) => {
  res.json({ success: true, scratchpads: scratchpadStore });
});

app.post('/api/scratchpads', async (req, res) => {
  try {
    const { id, title = 'Untitled Scratchpad', category = 'working-memory', content = '', tags = [] } = req.body;
    const now = new Date().toISOString();
    const hfidHash = crypto.createHash('sha256').update(content + title + now).digest('hex');

    const existingIdx = scratchpadStore.findIndex(s => s.id === id);
    if (existingIdx >= 0) {
      scratchpadStore[existingIdx] = {
        ...scratchpadStore[existingIdx],
        title,
        category,
        content,
        tags,
        hfidHash,
        updatedAt: now
      };
      persistScratchpads(scratchpadStore);
      return res.json({ success: true, scratchpad: scratchpadStore[existingIdx] });
    }

    const newPad: ScratchpadRecord = {
      id: id || `sp-${Date.now()}`,
      title,
      category,
      content,
      tags,
      hfidHash,
      attested: true,
      createdAt: now,
      updatedAt: now
    };
    scratchpadStore.unshift(newPad);
    persistScratchpads(scratchpadStore);
    res.json({ success: true, scratchpad: newPad });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

app.delete('/api/scratchpads/:id', (req, res) => {
  scratchpadStore = scratchpadStore.filter(s => s.id !== req.params.id);
  persistScratchpads(scratchpadStore);
  res.json({ success: true });
});

// =========================================================================
// UNLOCKED PREMIER AGENT CAPABILITY MATRIX (Live Search + VM Code Eval)
// =========================================================================
app.post('/api/agent/tool-invoke', async (req, res) => {
  try {
    const { toolName, args = {} } = req.body || {};
    const startTime = Date.now();
    let output: any = {};

    switch (toolName) {
      case 'web_search': {
        const searchRes = await executeServerSovereignTool('webSearch', { query: args.query || 'software architecture' });
        output = {
          success: searchRes.success,
          results: Array.isArray(searchRes.output) ? searchRes.output : []
        };
        break;
      }
      case 'code_eval': {
        const code = String(args.code || '').trim();
        if (!code) {
          return res.status(400).json({ success: false, error: 'args.code is required' });
        }
        const logs: string[] = [];
        const sandbox: Record<string, any> = {
          args: args.input || {},
          Math,
          JSON,
          Date,
          console: {
            log: (...items: any[]) => logs.push(items.map(i => typeof i === 'string' ? i : JSON.stringify(i)).join(' ')),
            warn: (...items: any[]) => logs.push('[WARN] ' + items.map(i => typeof i === 'string' ? i : JSON.stringify(i)).join(' ')),
            error: (...items: any[]) => logs.push('[ERR] ' + items.map(i => typeof i === 'string' ? i : JSON.stringify(i)).join(' '))
          }
        };
        const evalStart = performance.now();
        let returnValue: any = undefined;
        let evalError: string | undefined;
        try {
          const ctx = vm.createContext(sandbox);
          const wrapped = `(function(){ ${code} })()`;
          returnValue = vm.runInContext(wrapped, ctx, { timeout: 2500 });
        } catch (err: any) {
          // Try evaluating as a standalone expression if function-body wrap failed syntax
          try {
            const ctx = vm.createContext(sandbox);
            returnValue = vm.runInContext(code, ctx, { timeout: 2500 });
          } catch (innerErr: any) {
            evalError = innerErr?.message || err?.message || 'Execution error';
          }
        }
        const execMs = (performance.now() - evalStart).toFixed(2);
        output = internalSecretsHandler.redactObject({
          executed: !evalError,
          sandbox: 'Node vm Isolated Context (2.5s timeout)',
          elapsedMs: Number(execMs),
          returnValue,
          stdout: logs.join('\n') || (evalError ? `Error: ${evalError}` : `Executed in ${execMs}ms`),
          ...(evalError ? { error: evalError } : {})
        });
        break;
      }
      case 'hfid_sign': {
        const payload = JSON.stringify(args.data || {});
        const sig = crypto.createHash('sha256').update(payload + ':AURELIUS').digest('hex');
        output = {
          hfidSignature: `0x${sig}`,
          algorithm: 'SHA-256',
          timestamp: new Date().toISOString()
        };
        break;
      }
      default: {
        const delegated = await executeServerSovereignTool(toolName, args);
        output = delegated.output;
      }
    }

    res.json({
      success: !output?.error,
      toolName,
      output: internalSecretsHandler.redactObject(output),
      elapsedMs: Date.now() - startTime
    });
  } catch (e: any) {
    res.status(500).json({ error: e.message });
  }
});



// 🗣️ High-Fidelity Native English Neural Text-To-Speech (TTS) Engine
// Strictly locks a single native English human voice across all paragraphs with 100% free open neural synthesis.
function splitServerTextForNeuralTts(text: string, maxLen: number = 210): string[] {
  const sentences = text.match(/[^.!?;]+[.!?;]+|[^.!?;]+$/g) || [text];
  const chunks: string[] = [];
  let current = '';

  for (const raw of sentences) {
    const s = raw.trim();
    if (!s) continue;
    if ((current + ' ' + s).trim().length <= maxLen) {
      current = (current + ' ' + s).trim();
    } else {
      if (current) chunks.push(current);
      if (s.length <= maxLen) {
        current = s;
      } else {
        const words = s.split(/\s+/);
        let buf = '';
        for (const w of words) {
          if ((buf + ' ' + w).trim().length <= maxLen) {
            buf = (buf + ' ' + w).trim();
          } else {
            if (buf) chunks.push(buf);
            buf = w;
          }
        }
        current = buf;
      }
    }
  }
  if (current) chunks.push(current);
  return chunks.filter(Boolean);
}

function resolveOpenEnglishNeuralVoiceId(
  voiceInput: string,
  accentInput?: string
): {
  neuralId: string;
  langCode: 'en-US' | 'en-GB';
  geminiVoiceName: 'Zephyr' | 'Puck' | 'Charon' | 'Kore' | 'Fenrir' | 'Aoede';
  speechStyle: string;
} {
  const v = (voiceInput || '').toLowerCase();
  const explicitAccent = (accentInput || '').toLowerCase();
  const wantsBritish =
    explicitAccent === 'en-gb' ||
    explicitAccent === 'gb' ||
    explicitAccent === 'uk' ||
    explicitAccent === 'british' ||
    v.includes('bella') ||
    v.includes('british') ||
    v.includes('uk') ||
    v.includes('oliver');

  const langCode: 'en-US' | 'en-GB' = wantsBritish ? 'en-GB' : 'en-US';
  const accentLabel =
    langCode === 'en-GB'
      ? 'Clear, natural, articulate native British English (standard UK) speaker, easy to understand, zero foreign accent'
      : 'Clear, natural, conversational native American English (standard US) speaker, easy to understand, zero foreign accent';

  if (v.includes('atlas') || v.includes('charon') || v.includes('daniel') || v.includes('george')) {
    return {
      neuralId: langCode === 'en-GB' ? 'en-GB-studio-male' : 'en-US-studio-male',
      langCode,
      geminiVoiceName: 'Charon',
      speechStyle: `Calm, grounded male voice. ${accentLabel}.`
    };
  }
  if (v.includes('fenrir') || v.includes('marcus') || v.includes('male') || v.includes('andrew')) {
    return {
      neuralId: langCode === 'en-GB' ? 'en-GB-deep-male' : 'en-US-deep-male',
      langCode,
      geminiVoiceName: 'Fenrir',
      speechStyle: `Direct, clear, resonant male voice. ${accentLabel}.`
    };
  }
  if (v.includes('puck')) {
    return {
      neuralId: langCode === 'en-GB' ? 'en-GB-crisp' : 'en-US-crisp',
      langCode,
      geminiVoiceName: 'Puck',
      speechStyle: `Sharp, energetic, natural peer voice. ${accentLabel}.`
    };
  }
  if (v.includes('zephyr') || wantsBritish) {
    return {
      neuralId: langCode === 'en-GB' ? 'en-GB-natural' : 'en-US-natural',
      langCode,
      geminiVoiceName: 'Zephyr',
      speechStyle: `Warm, crisp, natural collaborator voice. ${accentLabel}.`
    };
  }
  if (v.includes('seraphina') || v.includes('claire') || v.includes('celeste') || v.includes('aoede')) {
    return {
      neuralId: langCode === 'en-GB' ? 'en-GB-warm' : 'en-US-warm',
      langCode,
      geminiVoiceName: 'Aoede',
      speechStyle: `Smooth, expressive studio voice. ${accentLabel}.`
    };
  }
  return {
    neuralId: langCode === 'en-GB' ? 'en-GB-clear' : 'en-US-clear',
    langCode,
    geminiVoiceName: 'Kore',
    speechStyle: `Clear, warm, natural studio voice. ${accentLabel}.`
  };
}

// Strict Native US / British English fallback neural MP3 (ONLY en-US or en-GB, never foreign or third-party TikTok voices)
async function synthesizeFreeNativeEnglishMp3(
  text: string,
  _neuralVoiceId: string,
  langCode: 'en-US' | 'en-GB' = 'en-US'
): Promise<Buffer | null> {
  const subChunks = splitServerTextForNeuralTts(text, 190);
  if (subChunks.length === 0) return null;
  const strictTl: 'en-US' | 'en-GB' = langCode === 'en-GB' ? 'en-GB' : 'en-US';

  try {
    const mp3Parts: Buffer[] = [];
    for (const chunk of subChunks) {
      const url = `https://translate.google.com/translate_tts?ie=UTF-8&q=${encodeURIComponent(chunk)}&tl=${encodeURIComponent(strictTl)}&client=tw-ob`;
      const r = await fetch(url, {
        headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)' },
        signal: AbortSignal.timeout(7000)
      });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const arrBuf = await r.arrayBuffer();
      if (arrBuf.byteLength === 0) throw new Error('Empty audio buffer');
      mp3Parts.push(Buffer.from(arrBuf));
    }
    if (mp3Parts.length > 0) {
      return Buffer.concat(mp3Parts);
    }
  } catch (_) {}

  return null;
}

function extractWavPcmAndFormat(buf: Buffer): {
  pcm: Buffer;
  sampleRate: number;
  numChannels: number;
  bitsPerSample: number;
} {
  let sampleRate = 24000;
  let numChannels = 1;
  let bitsPerSample = 16;
  if (buf.length >= 44 && buf.toString('ascii', 0, 4) === 'RIFF' && buf.toString('ascii', 8, 12) === 'WAVE') {
    let offset = 12;
    while (offset + 8 <= buf.length) {
      const subId = buf.toString('ascii', offset, offset + 4);
      const subSize = buf.readUInt32LE(offset + 4);
      if (subId === 'fmt ' && offset + 24 <= buf.length) {
        numChannels = buf.readUInt16LE(offset + 10) || 1;
        sampleRate = buf.readUInt32LE(offset + 12) || 24000;
        bitsPerSample = buf.readUInt16LE(offset + 22) || 16;
      } else if (subId === 'data') {
        const start = offset + 8;
        const end = subSize > 0 && start + subSize <= buf.length ? start + subSize : buf.length;
        return { pcm: buf.subarray(start, end), sampleRate, numChannels, bitsPerSample };
      }
      offset += 8 + subSize + (subSize % 2);
    }
    return { pcm: buf.subarray(44), sampleRate, numChannels, bitsPerSample };
  }
  return { pcm: buf, sampleRate, numChannels, bitsPerSample };
}

function buildCanonicalWavBuffer(
  pcmParts: Buffer[],
  sampleRate: number = 24000,
  numChannels: number = 1,
  bitsPerSample: number = 16
): Buffer {
  const totalPcm = Buffer.concat(pcmParts);
  const byteRate = sampleRate * numChannels * (bitsPerSample / 8);
  const blockAlign = numChannels * (bitsPerSample / 8);
  const header = Buffer.alloc(44);
  header.write('RIFF', 0, 'ascii');
  header.writeUInt32LE(36 + totalPcm.length, 4);
  header.write('WAVE', 8, 'ascii');
  header.write('fmt ', 12, 'ascii');
  header.writeUInt32LE(16, 16);
  header.writeUInt16LE(1, 20);
  header.writeUInt16LE(numChannels, 22);
  header.writeUInt32LE(sampleRate, 24);
  header.writeUInt32LE(byteRate, 28);
  header.writeUInt16LE(blockAlign, 32);
  header.writeUInt16LE(bitsPerSample, 34);
  header.write('data', 36, 'ascii');
  header.writeUInt32LE(totalPcm.length, 40);
  return Buffer.concat([header, totalPcm]);
}

// Primary Studio Native English TTS: Gemini 3.8 Flash Lite TTS -> Gemini 3.8 Flash TTS -> Gemini 2.5 Flash TTS -> strict en-US/en-GB neural MP3
// Supports infinite-length text via automatic sentence-aligned multi-chunk synthesis + lossless WAV/PCM stitching.
async function synthesizeNativeEnglishStudioAudio(
  cleanText: string,
  voiceInput: string = 'Zephyr',
  accentInput?: string
): Promise<{ audioUrl: string; voice: string; mimeType: string; model: string; langCode: 'en-US' | 'en-GB' } | null> {
  const voiceConfig = resolveOpenEnglishNeuralVoiceId(voiceInput, accentInput);
  const cloudTtsKey = getActiveGeminiApiKey();
  const textSegments = cleanText.length > 620 ? splitServerTextForNeuralTts(cleanText, 560) : [cleanText];

  if (cloudTtsKey && textSegments.length > 0) {
    const devAi = getPermanentDeveloperAiClient();
    const ttsCandidates = ['gemini-3.8-flash-lite-tts', 'gemini-3.8-flash-tts', 'gemini-2.5-flash-preview-tts'];
    for (const ttsModel of ttsCandidates) {
      if (isModelInCooldown(ttsModel)) continue;
      try {
        const isGemini38 = ttsModel.startsWith('gemini-3.8');
        if (textSegments.length === 1) {
          const partPayload: any = isGemini38
            ? {
                text: textSegments[0],
                speechMetadata: {
                  style: voiceConfig.speechStyle
                }
              }
            : {
                text: textSegments[0]
              };

          const response = await withPromiseTimeout(
            devAi.models.generateContent({
              model: ttsModel,
              contents: [{ role: 'user', parts: [partPayload] }],
              config: {
                responseModalities: ['AUDIO'],
                speechConfig: {
                  voiceConfig: {
                    prebuiltVoiceConfig: {
                      voiceName: voiceConfig.geminiVoiceName
                    }
                  }
                }
              }
            }),
            18000,
            `tts:${ttsModel}`
          );

          const found = response.candidates?.[0]?.content?.parts?.find((p: any) => p.inlineData?.data);
          if (found?.inlineData?.data) {
            const rawMime = String(found.inlineData.mimeType || 'audio/wav');
            if (rawMime.toLowerCase().includes('pcm') && !rawMime.toLowerCase().includes('wav')) {
              const rawBuf = Buffer.from(found.inlineData.data, 'base64');
              const wavBuf = buildCanonicalWavBuffer([rawBuf], 24000, 1, 16);
              return {
                audioUrl: `data:audio/wav;base64,${wavBuf.toString('base64')}`,
                voice: voiceConfig.geminiVoiceName,
                mimeType: 'audio/wav',
                model: ttsModel,
                langCode: voiceConfig.langCode
              };
            }
            return {
              audioUrl: `data:${rawMime};base64,${found.inlineData.data}`,
              voice: voiceConfig.geminiVoiceName,
              mimeType: rawMime,
              model: ttsModel,
              langCode: voiceConfig.langCode
            };
          }
        } else {
          const pcmParts: Buffer[] = [];
          let detectedRate = 24000;
          let detectedChannels = 1;
          let detectedBits = 16;

          for (const seg of textSegments) {
            const partPayload: any = isGemini38
              ? {
                  text: seg,
                  speechMetadata: {
                    style: voiceConfig.speechStyle
                  }
                }
              : {
                  text: seg
                };

            const response = await withPromiseTimeout(
              devAi.models.generateContent({
                model: ttsModel,
                contents: [{ role: 'user', parts: [partPayload] }],
                config: {
                  responseModalities: ['AUDIO'],
                  speechConfig: {
                    voiceConfig: {
                      prebuiltVoiceConfig: {
                        voiceName: voiceConfig.geminiVoiceName
                      }
                    }
                  }
                }
              }),
              20000,
              `tts:${ttsModel}:chunk`
            );

            const found = response.candidates?.[0]?.content?.parts?.find((p: any) => p.inlineData?.data);
            if (!found?.inlineData?.data) {
              throw new Error(`Missing audio segment from ${ttsModel}`);
            }
            const segBuf = Buffer.from(found.inlineData.data, 'base64');
            const parsed = extractWavPcmAndFormat(segBuf);
            detectedRate = parsed.sampleRate;
            detectedChannels = parsed.numChannels;
            detectedBits = parsed.bitsPerSample;
            pcmParts.push(parsed.pcm);
          }

          if (pcmParts.length > 0) {
            const fullWav = buildCanonicalWavBuffer(pcmParts, detectedRate, detectedChannels, detectedBits);
            return {
              audioUrl: `data:audio/wav;base64,${fullWav.toString('base64')}`,
              voice: voiceConfig.geminiVoiceName,
              mimeType: 'audio/wav',
              model: ttsModel,
              langCode: voiceConfig.langCode
            };
          }
        }
      } catch (cloudErr: any) {
        applyModelCooldown(ttsModel, cloudErr);
      }
    }
  }

  // Zero-key / quota-safe fallback: strictly native en-US or en-GB neural MP3 (handles arbitrary multi-chunk length)
  const fallbackMp3 = await synthesizeFreeNativeEnglishMp3(cleanText, voiceConfig.neuralId, voiceConfig.langCode);
  if (fallbackMp3 && fallbackMp3.length > 0) {
    return {
      audioUrl: `data:audio/mpeg;base64,${fallbackMp3.toString('base64')}`,
      voice: voiceConfig.neuralId,
      mimeType: 'audio/mpeg',
      model: `native-english-${voiceConfig.langCode.toLowerCase()}`,
      langCode: voiceConfig.langCode
    };
  }

  return null;
}

app.post('/api/tts', async (req, res) => {
  try {
    const { text, voice = 'Zephyr', accent = 'en-US' } = req.body;
    if (!text || typeof text !== 'string') {
      return res.status(400).json({ error: 'Text input is required for voice synthesis.' });
    }

    const cleanText = text
      .replace(/<think>[\s\S]*?<\/think>/gi, ' ')
      .replace(/```[\s\S]*?```/g, ' ')
      .replace(/~~~[\s\S]*?~~~/g, ' ')
      .replace(/^\d{1,5}\s*\|\s+.*$/gm, ' ')
      .replace(/\b(?:\/?[\w.-]+\/)+([\w.-]+)\.(?:tsx|ts|jsx|js|json|md|css|py|sh)(?::\d+(?::\d+)?)?\b/gi, '$1')
      .replace(/https?:\/\/[^\s)]+/gi, ' ')
      .replace(/[*_~#|>]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    if (!cleanText) {
      return res.status(400).json({ error: 'No speakable oral narrative found in text.' });
    }

    const synthesized = await synthesizeNativeEnglishStudioAudio(cleanText, voice, accent);
    if (synthesized) {
      return res.json({
        success: true,
        ...synthesized
      });
    }

    res.json({
      success: false,
      error: 'SYNTHESIS_FALLBACK',
      fallback: 'browser',
      message: 'Routing speech through strictly verified native English browser voice.'
    });
  } catch (err: any) {
    console.warn('[TTS] Voice synthesis request notice:', err?.message || err);
    res.json({
      success: false,
      error: 'SYNTHESIS_FALLBACK',
      fallback: 'browser',
      message: 'Routing speech through strictly verified native English browser voice.'
    });
  }
});

