  console.log(`Gemini Live API client connected (${liveModel}, user=${wsUser?.username || 'local'}, voice=${activeVoiceName}, accent=${activeAccentCode}, peer=${peerMode}, resume=${isResumeRequest}, sessionId=${activeVoiceSessionId})`);

